        {{{1U, 33U}, {5U, 84U}}, {1U, 1023U}},
        {{{0U, 986U}, {4U, 446U}}, {2U, 1023U}},
        {{{3U, 682U}, {7U, 137U}}, {3U, 1023U}},
    };
    
    std::uint32_t aCountSource[8][1024];
    std::uint32_t aCountDestination[4][1024];
    memset(aCountSource, 0, sizeof(aCountSource));
    memset(aCountDestination, 0, sizeof(aCountDestination));
    
    for (std::size_t aRollIndex=0; aRollIndex<4096; aRollIndex++) {
        FoldingRoll aRoll = aRolls[aRollIndex];
        for (std::size_t aSourceIndex=0; aSourceIndex<2; aSourceIndex++) {
            FoldingPiece aSource = aRoll.mSources[aSourceIndex];
            if ((aSource.mLane >= 8U) || (aSource.mBlock >= 1024U)) {
                XCTFail("test_CollapseFold (8): source piece is out of range. (roll = %zu, source slot = %zu, lane = %zu, block = %zu)",
                        aRollIndex,
                        aSourceIndex,
                        static_cast<std::size_t>(aSource.mLane),
                        static_cast<std::size_t>(aSource.mBlock));
                return;
            }
        }

        FoldingPiece aDestination = aRoll.mDestination;
        if ((aDestination.mLane >= 4U) ||
            (aDestination.mBlock >= 1024U)) {
            XCTFail("test_CollapseFold (8): destination piece is out of range. (roll = %zu, lane = %zu, block = %zu)",
                    aRollIndex,
                    static_cast<std::size_t>(aDestination.mLane),
                    static_cast<std::size_t>(aDestination.mBlock));
            return;
        }
    }

    for (std::size_t aRollIndex=0; aRollIndex<4096; aRollIndex++) {
        FoldingRoll aRoll = aRolls[aRollIndex];
        for (std::size_t aSourceIndex=0; aSourceIndex<2; aSourceIndex++) {
            FoldingPiece aSource = aRoll.mSources[aSourceIndex];
            aCountSource[aSource.mLane][aSource.mBlock]++;
        }

        FoldingPiece aDestination = aRoll.mDestination;
        aCountDestination[aDestination.mLane][aDestination.mBlock]++;
    }

    for (std::size_t aSourceLaneIndex=0; aSourceLaneIndex<8; aSourceLaneIndex++) {
        for (std::size_t aBlockIndex=0; aBlockIndex<1024; aBlockIndex++) {
            if (aCountSource[aSourceLaneIndex][aBlockIndex] != 1) {
                XCTFail("test_CollapseFold (8): expecting every source block index to be used exactly once. (source = %zu, block index = %zu, count = %zu)",
                        aSourceLaneIndex,
                        aBlockIndex,
                        static_cast<std::size_t>(aCountSource[aSourceLaneIndex][aBlockIndex]));
                return;
            }
        }
    }

    for (std::size_t aDestinationIndex=0; aDestinationIndex<4; aDestinationIndex++) {
        for (std::size_t aBlockIndex=0; aBlockIndex<1024; aBlockIndex++) {
            if (aCountDestination[aDestinationIndex][aBlockIndex] != 1) {
                XCTFail("test_CollapseFold (8): expecting every destination piece to be written exactly once. (lane = %zu, block = %zu, count = %zu)",
                        aDestinationIndex,
                        aBlockIndex,
                        static_cast<std::size_t>(aCountDestination[aDestinationIndex][aBlockIndex]));
                return;
            }
        }
    }
    
}


